import sqlite3
import hashlib
import json
from contextlib import contextmanager

if sqlite3.sqlite_version_info < (3, 25, 0):
    raise RuntimeError("SQLite 3.25 or later is required")

db = sqlite3.connect("enterprise_cohorts.sqlite3", timeout=30, isolation_level=None)
db.row_factory = sqlite3.Row
db.execute("PRAGMA foreign_keys = ON")
db.execute("PRAGMA journal_mode = WAL")
db.execute("PRAGMA synchronous = FULL")
db.execute("PRAGMA busy_timeout = 30000")

db.executescript("""
CREATE TABLE IF NOT EXISTS leads (
    lead_id TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    source_key TEXT NOT NULL,
    cohort TEXT NOT NULL CHECK(length(cohort) = 7),
    fingerprint TEXT NOT NULL,
    score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100),
    state TEXT NOT NULL CHECK(state IN ('pending','verified','accepted','rejected')),
    version INTEGER NOT NULL DEFAULT 0,
    UNIQUE(client_id, source_key)
);
CREATE TABLE IF NOT EXISTS state_events (
    event_key TEXT PRIMARY KEY,
    lead_id TEXT NOT NULL REFERENCES leads(lead_id),
    from_state TEXT NOT NULL,
    to_state TEXT NOT NULL,
    evidence_ref TEXT NOT NULL,
    expected_version INTEGER NOT NULL,
    result_version INTEGER NOT NULL,
    UNIQUE(lead_id, result_version)
);
CREATE TABLE IF NOT EXISTS invoices (
    invoice_key TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    cohort TEXT NOT NULL CHECK(length(cohort) = 7),
    lead_id TEXT UNIQUE REFERENCES leads(lead_id),
    cents INTEGER NOT NULL CHECK(cents > 0)
);
CREATE TABLE IF NOT EXISTS cash_events (
    bank_account TEXT NOT NULL,
    bank_tx TEXT NOT NULL,
    invoice_key TEXT NOT NULL REFERENCES invoices(invoice_key),
    booked_period TEXT NOT NULL CHECK(length(booked_period) = 7),
    cents INTEGER NOT NULL CHECK(cents > 0),
    PRIMARY KEY(bank_account, bank_tx)
);
CREATE TABLE IF NOT EXISTS expenses (
    event_key TEXT PRIMARY KEY,
    period TEXT NOT NULL CHECK(length(period) = 7),
    category TEXT NOT NULL,
    cents INTEGER NOT NULL CHECK(cents > 0)
);
""")

@contextmanager
def atomic():
    db.execute("BEGIN IMMEDIATE")
    try:
        yield
        db.execute("COMMIT")
    except BaseException:
        if db.in_transaction:
            db.execute("ROLLBACK")
        raise

def digest(value):
    payload = json.dumps(value, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()

def period_check(value):
    if not isinstance(value, str) or len(value) != 7:
        raise ValueError("Use a YYYY-MM service period")
    if value[4] != "-" or not value[:4].isdigit() or not value[5:].isdigit():
        raise ValueError("Use a YYYY-MM service period")
    if not 1 <= int(value[5:]) <= 12:
        raise ValueError("Month must be between one and twelve")

def positive_cents(value):
    if type(value) is not int or value <= 0:
        raise ValueError("Money must be positive integer cents")

def transition(lead_id, target, evidence, expected_version, event_key):
    if not evidence or not event_key:
        raise ValueError("Review evidence and immutable event key are required")
    if type(expected_version) is not int or expected_version < 0:
        raise ValueError("Expected version must be a nonnegative integer")
    with atomic():
        old = db.execute(
            "SELECT * FROM state_events WHERE event_key=?", (event_key,)
        ).fetchone()
        if old is not None:
            recorded = (
                old["lead_id"], old["to_state"], old["evidence_ref"],
                old["expected_version"],
            )
            if recorded != (lead_id, target, evidence, expected_version):
                raise ValueError("Review event key conflicts with recorded evidence")
            return old["result_version"]
        lead = db.execute(
            "SELECT * FROM leads WHERE lead_id=?", (lead_id,)
        ).fetchone()
        if lead is None:
            raise ValueError("Lead does not exist")
        allowed = {
            "pending": {"verified", "rejected"},
            "verified": {"accepted", "rejected"},
            "accepted": set(),
            "rejected": set(),
        }
        if lead["version"] != expected_version:
            raise ValueError("Stale review version; reload before deciding")
        if target not in allowed[lead["state"]]:
            raise ValueError("Requested state transition is prohibited")
        changed = db.execute(
            "UPDATE leads SET state=?, version=version+1 WHERE lead_id=? AND version=?",
            (target, lead_id, expected_version),
        ).rowcount
        if changed != 1:
            raise RuntimeError("Concurrent state change prevented")
        result_version = expected_version + 1
        db.execute(
            "INSERT INTO state_events VALUES (?, ?, ?, ?, ?, ?, ?)",
            (
                event_key, lead_id, lead["state"], target, evidence,
                expected_version, result_version,
            ),
        )
        if target == "accepted":
            db.execute(
                "INSERT INTO invoices VALUES (?, ?, ?, ?, ?)",
                (
                    "opportunity:" + lead_id, lead["client_id"],
                    lead["cohort"], lead_id, 375000,
                ),
            )
    return result_version

def retainer(client, period, cents=1250000):
    period_check(period)
    positive_cents(cents)
    if not client:
        raise ValueError("Client identifier is required")
    key = "retainer:" + digest([client, period])
    expected = (client, period, None, cents)
    with atomic():
        old = db.execute(
            "SELECT client_id, cohort, lead_id, cents FROM invoices WHERE invoice_key=?",
            (key,),
        ).fetchone()
        if old is not None:
            if tuple(old) != expected:
                raise ValueError("Retainer conflicts with existing earned charge")
        else:
            db.execute("INSERT INTO invoices VALUES (?, ?, ?, ?, ?)", (key,) + expected)
    return key

def paid_expense(key, period, category, cents):
    period_check(period)
    positive_cents(cents)
    if not key or not category:
        raise ValueError("Expense identity and category are required")
    expected = (period, category, cents)
    with atomic():
        old = db.execute(
            "SELECT period, category, cents FROM expenses WHERE event_key=?", (key,)
        ).fetchone()
        if old is not None:
            if tuple(old) != expected:
                raise ValueError("Expense event conflicts with recorded cost")
        else:
            db.execute("INSERT INTO expenses VALUES (?, ?, ?, ?)", (key,) + expected)

def receipt(account, bank_tx, invoice_key, period, cents):
    period_check(period)
    positive_cents(cents)
    if not account or not bank_tx:
        raise ValueError("Bank account and transaction identity are required")
    expected = (invoice_key, period, cents)
    with atomic():
        old = db.execute(
            "SELECT invoice_key, booked_period, cents FROM cash_events "
            "WHERE bank_account=? AND bank_tx=?",
            (account, bank_tx),
        ).fetchone()
        if old is not None:
            if tuple(old) != expected:
                raise ValueError("Bank posting conflicts with its existing allocation")
            return
        invoice = db.execute(
            "SELECT cents FROM invoices WHERE invoice_key=?", (invoice_key,)
        ).fetchone()
        if invoice is None:
            raise ValueError("Receipt requires an existing invoice")
        received = db.execute(
            "SELECT COALESCE(SUM(cents), 0) FROM cash_events WHERE invoice_key=?",
            (invoice_key,),
        ).fetchone()[0]
        if received + cents > invoice["cents"]:
            raise ValueError("Receipt exceeds remaining invoice balance")
        db.execute(
            "INSERT INTO cash_events VALUES (?, ?, ?, ?, ?)",
            (account, bank_tx, invoice_key, period, cents),
        )
